package org.community.giving;
import jakarta.persistence.*;
@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames={"election_id","member_id","category","subcategory"})) public class Candidate { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="election_id") public Long electionId; @Column(name="member_id") public Long memberId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="election_id",insertable=false,updatable=false,foreignKey=@ForeignKey(name="fk_candidate_election")) public Election election; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="member_id",insertable=false,updatable=false,foreignKey=@ForeignKey(name="fk_candidate_member")) public Member member; @Column(length=255) public String profilePicImage; public String memberName, category, subcategory, post; public boolean winner=false; public Integer voteCount=0; public boolean feePaid=false; }
